from typing import *
class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        dp = [[0 for _ in range(n+1)] for _ in range(k+1)]
        cur_sum = 0

        # Calculate the prefix sums
        for i in range(1, n+1):
            cur_sum += nums[i-1]
            dp[1][i] = cur_sum

        # Fill the DP table
        for i in range(2, k+1):
            for j in range(m, n+1):
                dp[i][j] = max(dp[i][j-m], dp[i-1][j-m] + cur_sum - dp[i-1][j])

        return dp[k][n]

from typing import *
from collections import *

class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        ans = [-1] * len(queries)
        pos = {}

        # Create a dictionary to store the last occurrence of each number
        for i in range(n):
            if nums[i] not in pos:
                pos[nums[i]] = i
            else:
                pos[nums[i]] = min(pos[nums[i]], i)

        # Iterate through each query
        for i, q in enumerate(queries):
            if q in pos:
                # Calculate the distance from the current position to the last occurrence of the number
                ans[i] = abs(q - pos[q])
            else:
                # If the number is not found, calculate the distances to the two closest occurrences
                if q + 1 < n:
                    ans[i] = abs(q - pos[nums[q + 1]])
                if q - 1 >= 0:
                    ans[i] = min(ans[i], abs(q - pos[nums[q - 1]]))

        return ans

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            if s[i] == 'N':
                prefix_sum[i+1] = prefix_sum[i] + 1
            elif s[i] == 'S':
                prefix_sum[i+1] = prefix_sum[i] - 1

        ans = 0
        left = 0
        right = 0
        while right < n:
            while right < n and prefix_sum[right] - prefix_sum[left] > k:
                left += 1

            ans = max(ans, right - left)
            right += 1

        return ans
